/* 55 statements in 13 lines, over the HISS-04 statement cap of 50 and far under the
 * length cap, which is the only thing measured for C. */
int many_statements(int count) {
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    count++; count++; count++; count++; count++;
    return count;
}
